@Store
@SuppressWarnings("unchecked")
@ConfiguredBy(RocksDbStoreConfigurationV2.class)
public class RocksDbStoreV2<K, V> implements AdvancedLoadWriteStore<K, V> {

    private RocksDB db;
    private Options options;

    @Override
    public void start() {
        this.options = new Options().setCreateIfMissing(true);
        this.db = RocksDB.open(options, dbPath);
    }

    @Override
    public void write(MarshalledEntry me) {
        byte[] keyBytes = marshaller.objectToByteBuffer(me.getKey());
        byte[] valBytes = me.getValueBytes().getBuf();
        db.put(keyBytes, valBytes);
    }

    @Override
    public MarshalledEntry load(Object key) {
        byte[] keyBytes = marshaller.objectToByteBuffer(key);
        byte[] valBytes = db.get(keyBytes);
        if (valBytes == null) return null;
        return entryFactory.create(key, valBytes);
    }

    @Override
    public void writeBatch(Iterable<MarshalledEntry<? extends K, ? extends V>> entries) {
        try (WriteBatch batch = new WriteBatch();
             WriteOptions writeOpts = new WriteOptions()) {
            for (MarshalledEntry entry : entries) {
                batch.put(marshaller.objectToByteBuffer(entry.getKey()), entry.getValueBytes().getBuf());
            }
            db.write(writeOpts, batch);
        }
    }
}

@ConfigurationFor(RocksDbStoreV2.class)
@BuiltBy(RocksDbStoreConfigurationBuilderV2.class)
@SerializedWith(RocksDbStoreConfigurationSerializerV2.class)
public class RocksDbStoreConfigurationV2 extends AbstractStoreConfiguration {
    final static AttributeDefinition<CompressionType> COMPRESSION_TYPE =
        AttributeDefinition.builder("compression-type", CompressionType.SNAPPY)
            .immutable()
            .autoPersist(false)
            .build();

    final static AttributeDefinition<Integer> BLOCK_SIZE =
        AttributeDefinition.builder("block-size", 4096)
            .immutable()
            .build();
}
